            let lengthOfPositionAttr = skinnedMesh.geometry.attributes.position.array.length;

            let exactTextureSizeNeeded = Math.ceil(Math.sqrt((lengthOfPositionAttr * lengthOfMorphAttributes / 3)));

            //if you are not happy with the texture size or want to speed up you can pass the texture size into this function
            let textureSizeUsed = textureSize || exactTextureSizeNeeded;

            // not to go above the limit of webgl2 
            textureSizeUsed = Math.min(16384, textureSizeUsed);

            let size = textureSizeUsed * textureSizeUsed;
            data = new Float32Array(3 * size);

            for (let v = 0; v < lengthOfPositionAttr; v += 3) {
                //Loop over all blendshapes
                for (let i = 0; i < lengthOfMorphAttributes; i++) {

