            skinnedMesh.geometry.addAttribute('vertIndex', new THREE.BufferAttribute(vertIndexs, 1));
            skinnedMesh.geometry.addAttribute('dataForMorphing', new THREE.BufferAttribute(data, 1));
            //CREATE DATA TEXTURE AND PLACE ON SHADER MAT
            let dataTexture = new THREE.DataTexture(data, textureSizeUsed, textureSizeUsed, THREE.RGBFormat, THREE.FloatType);
            dataTexture.needsUpdate = true;

            //Disable all morphTarget logic by setting appropriate flags
            skinnedMesh.material.morphTargets = false;
            skinnedMesh.material.morphNormals = false;

            const morphTargetDeclarations = `
