            skinnedMesh.material.onBeforeCompile = function (shader) {
                // Add new necessary uniforms
                shader.uniforms.texture0 = {
                    type: 't',
                    value: dataTexture
                };
                // Now when we change the morphTargetInfluences it's linked to show up in the 
